import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib

app = Flask(__name__)

UPLOAD_DIR = '/var/spool/converter/input'
OUTPUT_DIR = '/var/spool/converter/output'
ALLOWED_EXTENSIONS = {'doc', 'docx', 'odt', 'rtf', 'txt'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def get_output_path(input_filename):
    base = os.path.splitext(input_filename)[0]
    return os.path.join(OUTPUT_DIR, base + '.pdf')

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

@app.route('/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document to PDF using LibreOffice headless mode.
    Supports custom output formatting via 'options' parameter.
    """
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'File type not allowed'}), 415

    filename = secure_filename(file.filename)
    input_path = os.path.join(UPLOAD_DIR, filename)
    file.save(input_path)

    # Build conversion command
    base_cmd = 'libreoffice --headless --convert-to pdf'

    # User-supplied conversion options (page range, quality, etc.)
    user_options = request.form.get('options', '')

    # Construct the full command with output directory
    cmd = f'{base_cmd} {user_options} --outdir {OUTPUT_DIR} {input_path}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=120,
            cwd='/tmp'
        )

        if result.returncode != 0:
            return jsonify({
                'error': 'Conversion failed',
                'detail': result.stderr.decode('utf-8', errors='replace')[:500]
            }), 500

        output_path = get_output_path(filename)
        if not os.path.exists(output_path):
            return jsonify({'error': 'Output file not generated'}), 500

        file_hash = hashlib.sha256(open(output_path, 'rb').read()).hexdigest()

        return jsonify({
            'status': 'success',
            'download_url': f'/download/{filename}',
            'sha256': file_hash
        })
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    finally:
        # Cleanup input file
        if os.path.exists(input_path):
            os.unlink(input_path)

@app.route('/download/<filename>', methods=['GET'])
def download(filename):
    safe_name = secure_filename(filename)
    base = os.path.splitext(safe_name)[0]
    output_path = os.path.join(OUTPUT_DIR, base + '.pdf')

    if not os.path.exists(output_path):
        return jsonify({'error': 'File not found'}), 404

    return send_file(output_path, mimetype='application/pdf')

@app.route('/batch', methods=['POST'])
def batch_convert():
    """Accept a JSON manifest of files already staged in UPLOAD_DIR."""
    manifest = request.get_json()
    if not manifest or 'files' not in manifest:
        return jsonify({'error': 'Invalid manifest'}), 400

    results = []
    for entry in manifest['files']:
        fname = secure_filename(entry.get('name', ''))
        opts = entry.get('options', '')
        input_path = os.path.join(UPLOAD_DIR, fname)
        if os.path.exists(input_path) and allowed_file(fname):
            cmd = f'libreoffice --headless --convert-to pdf {opts} --outdir {OUTPUT_DIR} {input_path}'
            r = subprocess.run(cmd, shell=True, capture_output=True, timeout=120)
            results.append({'file': fname, 'success': r.returncode == 0})

    return jsonify({'results': results})

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    os.makedirs(OUTPUT_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
